//! Runtime tokens refer to a configuration applied by the platform, not just
//! a file generated by the UI. All metadata remains in private user storage.
use crate::{
    static_exit,
    storage::{Storage, sha256},
};
use anyhow::{Result, ensure};
use serde_json::{Value, json};
use std::collections::{HashMap, HashSet};

pub struct Ports {
    pub mixed: u16,
    pub controller: u16,
    pub probe: u16,
    pub current: u16,
    pub scan: u16,
}
impl Ports {
    pub fn from_payload(p: &Value) -> Self {
        let read = |key: &str, default| match p.get(key).filter(|v| !v.is_null()) {
            None => default,
            Some(v) => v.as_u64().and_then(|n| u16::try_from(n).ok()).unwrap_or(0),
        };
        Self {
            mixed: read("mixedPort", 7890),
            controller: read("controllerPort", 9090),
            probe: read("probePort", 9091),
            current: read("exitProbePort", 9092),
            scan: read("scanPort", 9093),
        }
    }
    pub fn validate(&self) -> Result<()> {
        let ports = [
            self.mixed,
            self.controller,
            self.probe,
            self.current,
            self.scan,
        ];
        ensure!(
            ports.iter().all(|p| *p > 0) && ports.into_iter().collect::<HashSet<_>>().len() == 5,
            "移动端代理、控制器和检测端口需要互不冲突的有效端口。"
        );
        Ok(())
    }
}

pub fn persist(
    store: &Storage,
    engine: &str,
    config: &Value,
    _settings: &Value,
    ports: &Ports,
    node_tags: HashMap<String, String>,
    selected: Value,
) -> Result<String> {
    let revision = sha256(&serde_json::to_vec(config)?);
    let has_scan = if engine == "mihomo" {
        config["listeners"]
            .as_array()
            .is_some_and(|l| l.iter().any(|v| v["name"] == static_exit::SCAN_LISTENER))
    } else {
        config["inbounds"]
            .as_array()
            .is_some_and(|l| l.iter().any(|v| v["tag"] == static_exit::SCAN_LISTENER))
    };
    let secret = if engine == "mihomo" {
        config["secret"].clone()
    } else {
        config["experimental"]["clash_api"]["secret"].clone()
    };
    let scan_exit = if engine == "mihomo" {
        config["proxies"]
            .as_array()
            .and_then(|v| v.iter().find(|v| v["name"] == static_exit::SCAN_EXIT))
    } else {
        config["outbounds"]
            .as_array()
            .and_then(|v| v.iter().find(|v| v["tag"] == static_exit::SCAN_EXIT))
    };
    let scan_key = sha256(&serde_json::to_vec(
        &json!({"engine":engine,"exit":scan_exit,"manifest":store.manifest()?["revision"],"nodes":node_tags}),
    )?);
    store.write("runtime-state/mobile-profile.json", &json!({"engine":engine,"companyKey":super::company::record_key(store)?,"scanPort":ports.scan,"scanKey":scan_key,"revision":revision,"settingsKey":settings_key(&store.settings()?)?,"manifestRevision":store.manifest()?["revision"],
        "mixed":ports.mixed,"controller":ports.controller,"probe":ports.probe,"current":ports.current,"scan":if has_scan {json!(ports.scan)}else{Value::Null},"secret":secret,"nodes":node_tags,"selectedTag":selected}))?;
    Ok(revision)
}

/// Presentation edits do not invalidate a running network profile.
pub(super) fn settings_key(settings: &Value) -> Result<String> {
    let mut value = json!({});
    for name in [
        "selectedProxy",
        "defaultOutlet",
        "unknownTraffic",
        "geoFallback",
        "vpnDomainRules",
        "directDomainRules",
        "specialCompatibilityRules",
        "ipv6",
        "lanDirect",
        "tailscaleDirect",
        "staticExit",
    ] {
        value[name] = settings[name].clone();
    }
    if settings["defaultOutlet"]["kind"] == "group" {
        value["nodeGroups"] = settings["nodeGroups"].clone();
    }
    Ok(sha256(&serde_json::to_vec(&value)?))
}
